// AI: below section was generated by an AI
(() => {
	"use strict";
	const assetBase = new URL("./", document.currentScript.src).pathname;
	const settings = window.location.pathname.startsWith(assetBase + "settings");
	function initializeBranding() {
		const body = document.body;
		if (!settings && !body.classList.contains("ct-control")) return;
		body.classList.add("ct-app");
		let header = document.getElementById("ctHeader");
		if (settings) {
			body.classList.add("ct-settings");
			header = document.createElement("header");
			header.id = "ctHeader";
			header.className = "ct-header";
			header.innerHTML = '<div class="ct-header-inner"><div class="ct-header-copy"><div class="ct-header-actions"></div><h1 class="ct-page-title">Settings</h1><div class="ct-page-subtitle"></div></div><img class="ct-page-logo" width="72" height="88" alt="CastleTek Lights"></div>';
			header.querySelector("img").src = assetBase + "castletek-logo.png";
			const heading = body.querySelector("h2");
			if (heading) header.querySelector(".ct-page-subtitle").appendChild(heading);
			else header.querySelector(".ct-page-subtitle").textContent = "Configure your controller";
			body.insertBefore(header, body.firstChild);
			if (!body.querySelector("form")) {
				const menu = document.createElement("main");
				menu.className = "ct-settings-menu";
				body.querySelectorAll(":scope > button").forEach(button => {
					if (button.id === "b") header.querySelector(".ct-header-actions").appendChild(button);
					else menu.appendChild(button);
				});
				body.insertBefore(menu, header.nextSibling);
			}
			const updateHeaderHeight = () => body.style.setProperty("--ct-header-height", header.offsetHeight + "px");
			updateHeaderHeight();
			if (typeof ResizeObserver === "function") new ResizeObserver(updateHeaderHeight).observe(header);
			else window.addEventListener("resize", updateHeaderHeight);
		}

		const nav = document.createElement("nav");
		nav.className = "ct-tab-bar";
		nav.setAttribute("aria-label", "Main navigation");
		const icons = {
			home: '<path d="m3 10 9-7 9 7v10H3zM9 20v-7h6v7"/>',
			design: '<path d="m4 17 11-11 3 3L7 20H4zm10-10 3 3m-8-7 1 2M3 9l2 1m14 5 2 1m-6 3 1 2"/>',
			settings: '<path d="M4 7h16M4 17h16M8 4v6m8 4v6"/>'
		};
		const links = {};
		for (const page of ["home", "design", "settings"]) {
			const link = (page === "settings" && document.getElementById("settingsLink")) || document.createElement("a");
			link.className = "";
			link.href = assetBase + (page === "settings" ? "settings" : "#" + page);
			link.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true">' + icons[page] + '</svg><span>' + page.charAt(0).toUpperCase() + page.slice(1) + '</span>';
			nav.appendChild(link);
			links[page] = link;
		}
		body.appendChild(nav);
		function selectPage() {
			const page = settings ? "settings" : window.location.hash === "#design" ? "design" : "home";
			Object.keys(links).forEach(key => {
				if (key === page) links[key].setAttribute("aria-current", "page");
				else links[key].removeAttribute("aria-current");
			});
			if (settings) return;
			// Keep controls and editor drafts mounted; tab changes never make controller requests.
			document.querySelectorAll("[data-ct-page]").forEach(section => { section.hidden = section.dataset.ctPage !== page; });
			document.getElementById("ctPageTitle").textContent = page === "design" ? "Design" : "Home";
			document.getElementById("ctPageSubtitle").textContent = page === "design" ? "Create your lighting look" : "Control your lights";
			document.title = (page === "design" ? "Design" : "Home") + " · CastleTek Lights";
			window.scrollTo(0, 0);
			window.dispatchEvent(new Event("castletek:pagechange"));
		}
		window.addEventListener("hashchange", selectPage);
		selectPage();
	}
	if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", initializeBranding, { once: true });
	else initializeBranding();
})();
// AI: end
